    q2 = Checks()
    q2a = q2.add('round(800*5.25/100*7/365*100,2)', '7-day repo cost (₹ lakh)')
    q2b = q2.add('round(800*5.50/100*7/365*100,2)', '7-day MSF cost (₹ lakh)')
