    q3b = q3.add('round((5.9+6.3+6.6)/3,2)', 'avg high quarters')

    k = Checks()
    k1 = k.add('round(200*5.25/100/365*100,2)', 'case repo cost')
    k2 = k.add('round(200*5.50/100/365*100,2)', 'case MSF cost')

